<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, apiMessage, downloadApiFile, type BuildMaterial, type ConstructionRecord, type RecyclingRecord, type TransportRecord } from '@/api'

const route = useRoute(); const router = useRouter(); const projectId = Number(route.params.id)
const project = ref<any>(null); const active = ref('overview'); const loading = ref(true); const error = ref('')
const build = ref<BuildMaterial[]>([]); const transport = ref<TransportRecord[]>([]); const construction = ref<ConstructionRecord[]>([]); const recycling = ref<RecyclingRecord[]>([]); const analysis = ref<any>(null); const versions = ref<any[]>([])
const buildFactors = ref<any[]>([]); const transportFactors = ref<any[]>([]); const factorTab = ref('build'); const buildSearch = ref(''); const buildType = ref('全部'); const transportSearch = ref(''); const transportEnergy = ref('全部'); const constructionSearch = ref(''); const constructionEnergy = ref('全部'); const recyclingSearch = ref(''); const recyclingType = ref('全部回收'); const editing = reactive<Record<string, boolean>>({}); const importLoading = ref('')
const materialForm = reactive({ factorConfigId: 0, quantity: 1, unitPrice: 1, marketPrice: null as number | null }); const transportForm = reactive({ factorConfigId: 0, transportedMaterial: '', transportQuantity: 1, transportDistance: 1, transportUnitPrice: 1 }); const constructionForm = reactive({ machineryName: '', energyType: '电力', shiftCount: 1, energyPerShift: 1, shiftUnitPrice: 1 }); const recyclingForm = reactive({ materialName: '', materialType: '其他', recyclingQuantity: 1, recyclingFactor: 0, recyclingCoefficient: 0, recyclingUnitPrice: 0 })
const title = computed(() => project.value?.projectName || '项目工作区'); const analysisStage = ref('build'); const costStage = ref('build')
const stageRows = computed(() => analysisStage.value==='build' ? build.value.map(x=>({name:x.materialName, quantity:x.quantity, unit:x.unit, factor:x.emissionFactor, emission:x.emissionAmount, share:analysis.value?.build?.totalEmission ? x.emissionAmount/analysis.value.build.totalEmission*100 : 0})) : analysisStage.value==='transport' ? transport.value.map(x=>({name:`${x.vehicleName} · ${x.transportedMaterial}`,quantity:x.transportQuantity,unit:'t',factor:x.emissionFactor,emission:x.emissionAmount,share:analysis.value?.transport?.totalEmission ? x.emissionAmount/analysis.value.transport.totalEmission*100 : 0})) : analysisStage.value==='construction' ? construction.value.filter(x=>x.machineryName.trim()).map(x=>({name:x.machineryName,quantity:x.shiftCount,unit:'台班',factor:x.emissionFactor,emission:x.emissionAmount/1000,share:analysis.value?.construction?.totalEmission ? x.emissionAmount/1000/analysis.value.construction.totalEmission*100 : 0})) : recycling.value.map(x=>({name:x.materialName,quantity:x.recyclingQuantity,unit:'',factor:x.recyclingFactor,emission:-x.reductionAmount,share:analysis.value?.recycling?.totalReduction ? x.reductionAmount/analysis.value.recycling.totalReduction*100 : 0})))
const costRows = computed(() => costStage.value==='build' ? analysis.value?.cost?.buildDetails || [] : costStage.value==='transport' ? transport.value.map(x=>({id:x.id,materialName:`${x.vehicleName} · ${x.transportedMaterial}`,totalPrice:x.transportTotalPrice,costShare:analysis.value?.cost?.totalCost ? x.transportTotalPrice/analysis.value.cost.totalCost*100 : 0,carbonCostIntensity:null})) : construction.value.filter(x=>x.machineryName.trim()).map(x=>({id:x.id,materialName:x.machineryName,totalPrice:x.totalPrice,costShare:analysis.value?.cost?.totalCost ? x.totalPrice/analysis.value.cost.totalCost*100 : 0,carbonCostIntensity:null})))
const categories = ['全部','混凝土','金属','钢材','砌体','保温材料','水泥及砂浆','玻璃','其他']; const energyTypes = ['全部','柴油','汽油']; const constructionTypes = ['全部','电力','柴油','汽油']; const recyclingTypes = ['全部回收','金属','保温材料','玻璃','其他']
const filteredBuild = computed(() => build.value.filter(x => (!buildSearch.value || x.materialName.includes(buildSearch.value)) && (buildType.value === '全部' || x.type === buildType.value)))
const filteredTransport = computed(() => transport.value.filter(x => (!transportSearch.value || `${x.vehicleName}${x.transportedMaterial}`.includes(transportSearch.value)) && (transportEnergy.value === '全部' || x.energyType === transportEnergy.value)))
const filteredConstruction = computed(() => construction.value.filter(x => (!constructionSearch.value || x.machineryName.includes(constructionSearch.value)) && (constructionEnergy.value === '全部' || x.energyType === constructionEnergy.value)))
const filteredRecycling = computed(() => recycling.value.filter(x => (!recyclingSearch.value || x.materialName.includes(recyclingSearch.value)) && (recyclingType.value === '全部回收' || x.materialType === recyclingType.value)))
const pageStats = computed(() => {
  const a = analysis.value
  if (active.value==='build') return [
    { label: '材料种类', value: String(build.value.length), unit: '种' },
    { label: '碳排放总量', value: format(a?.build?.totalEmission, 3), unit: 'tCO₂e' },
    { label: '建材总成本', value: format(a?.build?.totalMaterialCost, 4), unit: '万元' },
    { label: '单位面积碳排', value: format(a?.build?.emissionPerArea, 2), unit: 'kgCO₂e/㎡' },
  ]
  if (active.value==='transport') return [
    { label: '运输记录', value: String(transport.value.length), unit: '条' },
    { label: '运输阶段碳排放', value: format(a?.transport?.totalEmission, 3), unit: 'tCO₂e' },
    ...Object.entries(a?.transport?.energyTotals || {}).map(([name, item]: [string, any]) => ({ label: `${name}排放`, value: `${format(item.emissionAmount,3)} · ${format(item.share,1)}%`, unit: '' })),
  ]
  if (active.value==='construction') return [
    { label: '施工碳排放总量', value: format(a?.construction?.totalEmission, 3), unit: 'tCO₂e' },
    { label: '机械台班总数', value: String(a?.construction?.totalShiftCount ?? 0), unit: '台班' },
    ...Object.entries(a?.construction?.energyTotals || {}).map(([name, item]: [string, any]) => ({ label: `${name}消耗`, value: format(item.energyTotal,3), unit: item.unit })),
  ]
  if (active.value==='recycling') return [
    { label: '可回收阶段总减碳排量', value: format(a?.recycling?.totalReduction, 3), unit: 'tCO₂e' },
    { label: '可回收材料总量', value: format(a?.recycling?.totalRecyclingQuantity, 3), unit: 't' },
    { label: '综合回收利用率', value: format(a?.recycling?.recyclingUtilizationRate, 2), unit: '%' },
    { label: '回收残值估算', value: format(a?.recycling?.estimatedResidualValue, 4), unit: '万元' },
  ]
  return []
})
function format(value: number | null | undefined, digits = 3) { return Number(value || 0).toLocaleString('zh-CN', { minimumFractionDigits: digits, maximumFractionDigits: digits }) }
function errorText(e: unknown) { return apiMessage(e, '操作失败') }
async function load() { loading.value = true; try { const [p,b,t,c,r,a,v,bf,tf] = await Promise.all([api.get(`/projects/${projectId}`),api.get(`/projects/${projectId}/build-materials`),api.get(`/projects/${projectId}/transport-records`),api.get(`/projects/${projectId}/construction-records`),api.get(`/projects/${projectId}/recycling-records`),api.get(`/projects/${projectId}/analysis`),api.get(`/projects/${projectId}/versions`),api.get(`/projects/${projectId}/build-factors`),api.get(`/projects/${projectId}/transport-factors`)]); project.value=p.data; build.value=b.data; transport.value=t.data; construction.value=c.data; recycling.value=r.data; analysis.value=a.data; versions.value=v.data; buildFactors.value=bf.data; transportFactors.value=tf.data; materialForm.factorConfigId ||= bf.data[0]?.id || 0; transportForm.factorConfigId ||= tf.data[0]?.id || 0 } catch(e) { error.value=errorText(e) } finally { loading.value=false } }
async function refresh() { const [b,t,c,r,a,v] = await Promise.all([api.get(`/projects/${projectId}/build-materials`),api.get(`/projects/${projectId}/transport-records`),api.get(`/projects/${projectId}/construction-records`),api.get(`/projects/${projectId}/recycling-records`),api.get(`/projects/${projectId}/analysis`),api.get(`/projects/${projectId}/versions`)]); build.value=b.data; transport.value=t.data; construction.value=c.data; recycling.value=r.data; analysis.value=a.data; versions.value=v.data }
async function action(fn: () => Promise<unknown>, success: string) { try { await fn(); ElMessage.success(success); await refresh() } catch(e) { ElMessage.error(errorText(e)) } }
async function addMaterial() { await action(() => api.post(`/projects/${projectId}/build-materials`, materialForm), '建材记录已添加') }
async function addTransport() { await action(() => api.post(`/projects/${projectId}/transport-records`, transportForm), '运输记录已添加') }
async function addConstruction() { await action(() => api.post(`/projects/${projectId}/construction-records`, constructionForm), '施工记录已添加') }
async function addRecycling() { await action(() => api.post(`/projects/${projectId}/recycling-records`, recyclingForm), '回收记录已添加') }
async function removeRecord(kind: string, id: number) { await ElMessageBox.confirm('确定删除这条记录吗？', '删除确认', { type: 'warning' }); await action(() => api.delete(`/projects/${projectId}/${kind}/${id}`), '记录已删除') }
async function editRecord(kind: string, row: any) { const fields = kind === 'build-materials' ? { quantity: row.quantity, marketPrice: row.marketPrice, unitPrice: row.unitPrice } : kind === 'transport-records' ? { transportedMaterial: row.transportedMaterial, transportQuantity: row.transportQuantity, transportDistance: row.transportDistance, transportUnitPrice: row.transportUnitPrice } : kind === 'construction-records' ? { shiftCount: row.shiftCount, shiftUnitPrice: row.shiftUnitPrice, energyPerShift: row.energyPerShift } : { recyclingQuantity: row.recyclingQuantity, recyclingCoefficient: row.recyclingCoefficient, recyclingUnitPrice: row.recyclingUnitPrice }; try { const result = await api.patch(`/projects/${projectId}/${kind}/${row.id}`, fields); if (kind === 'recycling-records' && Number(result.data.recyclingQuantity) < Number(row.recyclingQuantity)) ElMessage.warning(`回收量不能超过对应建材用量，已按上限 ${result.data.recyclingQuantity} 计算`); else ElMessage.success('记录已更新'); await refresh() } catch(e) { ElMessage.error(errorText(e)) } finally { editing[`${kind}-${row.id}`] = false } }
async function importFile(kind: string, event: Event) { const input = event.target as HTMLInputElement; const file = input.files?.[0]; if (!file) return; if (file.size > 20 * 1024 * 1024) { ElMessage.error('Excel 文件不能超过 20MB'); return }; importLoading.value=kind; const data = new FormData(); data.append('file', file); try { const result = await api.post(`/projects/${projectId}/imports/${kind}`, data); ElMessage.success(`导入 ${result.data.imported} 条，跳过 ${result.data.skippedRows || 0} 条`); await refresh() } catch(e) { ElMessage.error(errorText(e)) } finally { importLoading.value=''; input.value='' } }
async function exportFile(kind: string) { try { await downloadApiFile(`/projects/${projectId}/exports/${kind}`, `${kind}.xlsx`); ElMessage.success('清单已导出') } catch(e) { ElMessage.error(errorText(e)) } }
async function saveProject() { try { await api.patch(`/projects/${projectId}`, project.value); ElMessage.success('项目资料已保存'); await load() } catch(e) { ElMessage.error(errorText(e)) } }
async function uploadModelImage(event: Event) { const input=event.target as HTMLInputElement; const file=input.files?.[0]; if(!file) return; if(file.size>10*1024*1024){ElMessage.error('模型图片不能超过 10MB');input.value='';return} const data=new FormData();data.append('file',file);try{const response=await api.post(`/projects/${projectId}/model-image`,data);project.value.modelImage=response.data.modelImage;project.value.modelImageName=response.data.modelImageName;ElMessage.success('模型图片已上传')}catch(e){ElMessage.error(errorText(e))}finally{input.value=''} }
async function removeModelImage() { try { await api.delete(`/projects/${projectId}/model-image`);project.value.modelImage=null;project.value.modelImageName='';ElMessage.success('模型图片已移除') } catch(e){ElMessage.error(errorText(e))} }
async function seedFactors() { await action(() => api.post(`/projects/${projectId}/factors/seed?overwrite=true`), '已重新装载旧版因子配置'); await load() }
async function saveVersion() { await action(async() => { const r=await api.post(`/projects/${projectId}/versions`); ElMessage.success(`已保存版本 v${r.data.versionNumber}`) }, '版本已保存') }
async function report(versionId: number, type: 'pdf'|'excel') { try { await downloadApiFile(`/projects/${projectId}/reports/${versionId}/${type}`, `${title.value}-报告.${type === 'pdf' ? 'pdf' : 'xlsx'}`) } catch(e) { ElMessage.error(errorText(e)) } }
async function reportCurrent(type: 'pdf'|'excel') { try { await downloadApiFile(`/projects/${projectId}/reports/current/${type}`, `${title.value}-当前核算.${type === 'pdf' ? 'pdf' : 'xlsx'}`) } catch(e) { ElMessage.error(errorText(e)) } }
const snapshotDialog = ref(false); const snapshotData = ref<any>(null)
async function viewVersion(versionId: number) { try { snapshotData.value = (await api.get(`/projects/${projectId}/versions/${versionId}`)).data; snapshotDialog.value = true } catch(e) { ElMessage.error(errorText(e)) } }
async function saveFactor(type: 'build'|'transport', row: any) { const path=type==='build'?'build-factors':'transport-factors'; try { if(row.id) await api.patch(`/projects/${projectId}/${path}/${row.id}`, row); else await api.post(`/projects/${projectId}/${path}`, row); ElMessage.success('因子配置已保存'); await load() } catch(e) { ElMessage.error(errorText(e)) } }
async function deleteFactor(type: 'build'|'transport', row: any) { await ElMessageBox.confirm('确定删除该因子配置吗？','删除确认',{type:'warning'}); await action(() => api.delete(`/projects/${projectId}/${type==='build'?'build-factors':'transport-factors'}/${row.id}`), '因子配置已删除'); await load() }
function newFactor() { if(factorTab.value==='build') buildFactors.value.push({category:'其他',name:'新建因子',emissionFactor:0,materialUnit:'t',recyclingFactor:0,recyclingCoefficient:0}); else transportFactors.value.push({vehicleName:'新建车辆',energyType:'柴油',emissionFactor:0}) }
onMounted(load)
</script>

<template>
  <div v-loading="loading" class="workspace-wrap"><div class="workspace-heading"><div><button class="back-link" @click="router.push('/projects')">← 返回项目台账</button><h1>{{ title }}</h1><p class="muted">{{ format(project?.buildingArea, 0) }} ㎡ · {{ project?.buildingType || '未填写类型' }} · {{ project?.accountingStandard }}</p></div><div class="heading-actions"><el-button @click="refresh">刷新</el-button><el-button @click="reportCurrent('excel')">导出当前 Excel</el-button><el-button @click="reportCurrent('pdf')">导出当前 PDF</el-button><el-button type="primary" @click="saveVersion">保存核算版本</el-button></div></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" />
    <nav class="workspace-tabs"><button v-for="tab in [['overview','总览'],['project','项目信息'],['factors','因子配置'],['build','建材生产'],['transport','运输'],['construction','施工'],['recycling','回收'],['analysis','分析'],['versions','版本'] ]" :key="tab[0]" :class="{active: active===tab[0]}" @click="active=tab[0]">{{ tab[1] }}</button></nav>
    <section v-if="active==='overview'" class="workspace-section"><div class="stat-grid"><div class="stat-card accent"><span>净碳排放</span><strong>{{ format(analysis?.emission?.netEmission) }}</strong><small>tCO₂e</small></div><div class="stat-card"><span>建材生产</span><strong>{{ format(analysis?.build?.totalEmission) }}</strong><small>tCO₂e</small></div><div class="stat-card"><span>运输阶段</span><strong>{{ format(analysis?.transport?.totalEmission) }}</strong><small>tCO₂e</small></div><div class="stat-card"><span>施工阶段</span><strong>{{ format(analysis?.construction?.totalEmission) }}</strong><small>tCO₂e</small></div><div class="stat-card"><span>回收减排</span><strong>{{ format(analysis?.recycling?.totalReduction) }}</strong><small>tCO₂e</small></div><div class="stat-card"><span>单位面积净排放</span><strong>{{ format(analysis?.emission?.unitAreaNetEmission, 2) }}</strong><small>kgCO₂e/㎡</small></div></div><div class="overview-columns"><div class="panel"><div class="panel-heading"><h2>生命周期阶段</h2><span class="muted">tCO₂e</span></div><div v-for="stage in analysis?.emission?.stages" :key="stage.name" class="bar-row"><span>{{ stage.name }}</span><div class="bar-track"><i :style="{width: `${Math.min(100, Math.abs(stage.emission)/(Math.abs(analysis?.emission?.netEmission||1))*25)}%`}"></i></div><strong>{{ format(stage.emission) }}</strong></div></div><div class="panel"><img v-if="project?.modelImage" class="overview-model-image" :src="project.modelImage" :alt="project.modelImageName || '项目模型'"/><div class="panel-heading"><h2>项目概况</h2></div><dl class="detail-list"><dt>项目地点</dt><dd>{{ [project?.province, project?.cityDistrict, project?.address].filter(Boolean).join(' ') || '未填写' }}</dd><dt>负责人</dt><dd>{{ project?.projectManager || '未填写' }}</dd><dt>设计使用年限</dt><dd>{{ project?.designLife || '未填写' }}</dd><dt>开工日期</dt><dd>{{ project?.startDate || '未填写' }}</dd><dt>计划竣工</dt><dd>{{ project?.plannedCompletionDate || '未填写' }}</dd><dt>记录总数</dt><dd>{{ build.length + transport.length + construction.length + recycling.length }}</dd></dl></div></div></section>
    <section v-else-if="active==='project'" class="workspace-section"><div class="panel"><div class="panel-heading"><h2>项目信息</h2><el-button type="primary" @click="saveProject">保存资料</el-button></div><el-form label-position="top"><div class="form-grid"><el-form-item label="项目名称"><el-input v-model="project.projectName"/></el-form-item><el-form-item label="建筑面积（㎡）"><el-input-number v-model="project.buildingArea" :min="0.000001" :controls="false" class="full-width"/></el-form-item><el-form-item label="建筑类型"><el-input v-model="project.buildingType"/></el-form-item><el-form-item label="结构类型"><el-input v-model="project.structureType"/></el-form-item><el-form-item label="楼层数"><el-input v-model="project.floorCount"/></el-form-item><el-form-item label="设计使用年限"><el-input v-model="project.designLife"/></el-form-item><el-form-item label="开工日期"><el-input v-model="project.startDate" type="date"/></el-form-item><el-form-item label="计划竣工日期"><el-input v-model="project.plannedCompletionDate" type="date"/></el-form-item><el-form-item label="项目负责人"><el-input v-model="project.projectManager"/></el-form-item><el-form-item label="核算标准"><el-input v-model="project.accountingStandard"/></el-form-item></div><el-form-item label="项目地址"><el-input v-model="project.address"/></el-form-item><el-form-item label="项目模型图片"><div class="image-tools"><input type="file" accept="image/png,image/jpeg,image/webp" @change="uploadModelImage"/><el-button v-if="project.modelImage" type="danger" plain @click="removeModelImage">移除图片</el-button></div><img v-if="project.modelImage" class="model-preview" :src="project.modelImage" :alt="project.modelImageName || '项目模型预览'"/><span v-if="project.modelImageName" class="muted">{{ project.modelImageName }}</span><span class="muted">支持 PNG、JPG、WEBP，最大 10MB</span></el-form-item></el-form></div></section>
    <section v-else-if="active==='factors'" class="workspace-section"><div class="panel"><div class="panel-heading"><div><h2>因子配置</h2><p class="muted">项目使用的因子由旧版配置文件初始化，可按项目调整</p></div><div><el-button @click="newFactor">新增</el-button><el-button type="primary" @click="seedFactors">重新装载旧版因子</el-button></div></div><div class="factor-tabs"><button :class="{active:factorTab==='build'}" @click="factorTab='build'">建材因子（{{ buildFactors.length }}）</button><button :class="{active:factorTab==='transport'}" @click="factorTab='transport'">运输因子（{{ transportFactors.length }}）</button></div><el-table v-if="factorTab==='build'" :data="buildFactors" stripe><el-table-column prop="category" label="类别"><template #default="s"><el-input v-model="s.row.category"/></template></el-table-column><el-table-column prop="name" label="名称"><template #default="s"><el-input v-model="s.row.name"/></template></el-table-column><el-table-column label="碳排因子"><template #default="s"><el-input-number v-model="s.row.emissionFactor" :min="0"/></template></el-table-column><el-table-column label="单位"><template #default="s"><el-input v-model="s.row.materialUnit"/></template></el-table-column><el-table-column label="回收因子"><template #default="s"><el-input-number v-model="s.row.recyclingFactor" :min="0"/></template></el-table-column><el-table-column label="回收系数"><template #default="s"><el-input-number v-model="s.row.recyclingCoefficient" :min="0"/></template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="saveFactor('build',s.row)">保存</el-button><el-button link type="danger" @click="deleteFactor('build',s.row)">删除</el-button></template></el-table-column></el-table><el-table v-else :data="transportFactors" stripe><el-table-column prop="vehicleName" label="车辆名称"><template #default="s"><el-input v-model="s.row.vehicleName"/></template></el-table-column><el-table-column prop="energyType" label="能源类型"><template #default="s"><el-select v-model="s.row.energyType"><el-option label="柴油" value="柴油"/><el-option label="汽油" value="汽油"/></el-select></template></el-table-column><el-table-column label="碳排因子"><template #default="s"><el-input-number v-model="s.row.emissionFactor" :min="0"/></template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="saveFactor('transport',s.row)">保存</el-button><el-button link type="danger" @click="deleteFactor('transport',s.row)">删除</el-button></template></el-table-column></el-table></div></section>
    <section v-else-if="active==='analysis'" class="workspace-section"><div class="analysis-grid"><div class="panel"><div class="panel-heading"><h2>生命周期碳排放</h2><span class="muted">建材 + 运输 + 施工 − 回收</span></div><div class="analysis-number">{{ format(analysis?.emission?.netEmission, 6) }} <small>tCO₂e</small></div><p class="muted">单位面积净排放 {{ format(analysis?.emission?.unitAreaNetEmission, 6) }} kgCO₂e/㎡</p><div class="stage-switch"><button v-for="stage in [{key:'build',label:'建材'},{key:'transport',label:'运输'},{key:'construction',label:'施工'},{key:'recycling',label:'回收'}]" :key="stage.key" :class="{active:analysisStage===stage.key}" @click="analysisStage=stage.key">{{ stage.label }}</button></div><el-table :data="stageRows" size="small"><el-table-column prop="name" label="材料/设备"/><el-table-column prop="quantity" label="用量"/><el-table-column prop="factor" label="因子"/><el-table-column prop="emission" label="排放（t）"/><el-table-column prop="share" label="占比"><template #default="s">{{ format(s.row.share,2) }}%</template></el-table-column></el-table><div v-for="stage in analysis?.emission?.stages" :key="stage.name" class="analysis-line"><span>{{ stage.name }}</span><strong>{{ format(stage.emission, 6) }}</strong></div></div><div class="panel"><div class="panel-heading"><h2>成本分析</h2><span class="muted">万元</span></div><div class="stage-switch"><button v-for="stage in [{key:'build',label:'建材'},{key:'transport',label:'运输'},{key:'construction',label:'施工'}]" :key="stage.key" :class="{active:costStage===stage.key}" @click="costStage=stage.key">{{ stage.label }}</button></div><div class="analysis-number">{{ format(analysis?.cost?.totalCost, 4) }} <small>万元</small></div><p class="muted">单位面积成本 {{ format(analysis?.cost?.unitAreaCost, 4) }} 元/㎡</p><div class="analysis-line"><span>建材成本</span><strong>{{ format(analysis?.cost?.buildCost, 4) }}</strong></div><div v-if="analysis?.cost?.topBuildMaterial" class="analysis-line"><span>成本最高建材</span><strong>{{ analysis.cost.topBuildMaterial.materialName }}</strong></div></div></div><div class="panel"><div class="panel-heading"><h2>{{ costStage==='build'?'建材':costStage==='transport'?'运输':'施工' }}成本明细</h2></div><el-table :data="costRows"><el-table-column prop="materialName" label="材料/设备"/><el-table-column prop="totalPrice" label="总价（万元）"><template #default="s">{{ format(s.row.totalPrice,4) }}</template></el-table-column><el-table-column prop="costShare" label="成本占比"><template #default="s">{{ format(s.row.costShare,2) }}%</template></el-table-column><el-table-column prop="carbonCostIntensity" label="成本碳强度（kg/元）"><template #default="s">{{ s.row.carbonCostIntensity==null ? '—' : format(s.row.carbonCostIntensity,6) }}</template></el-table-column></el-table></div><div class="panel"><h2>建材排放明细</h2><el-table :data="analysis?.emission?.buildMaterialDetails || []"><el-table-column prop="rank" label="排名" width="80"/><el-table-column prop="materialName" label="材料"/><el-table-column prop="type" label="类型"/><el-table-column prop="quantity" label="用量"/><el-table-column prop="unit" label="单位"/><el-table-column prop="emissionFactor" label="因子"/><el-table-column prop="emissionAmount" label="排放（t）"/><el-table-column prop="share" label="占比"><template #default="s">{{ format(s.row.share, 2) }}%</template></el-table-column></el-table></div></section>
    <section v-else-if="active==='versions'" class="workspace-section"><div class="panel"><div class="panel-heading"><div><h2>核算版本</h2><p class="muted">版本保存后数据快照不可变</p></div><el-button type="primary" @click="saveVersion">保存当前版本</el-button></div><el-table :data="versions"><el-table-column prop="versionNumber" label="版本" width="90"><template #default="scope">v{{ scope.row.versionNumber }}</template></el-table-column><el-table-column prop="createdAt" label="保存时间"/><el-table-column prop="createdBy" label="保存人"/><el-table-column prop="netEmission" label="净排放（t）"><template #default="scope">{{ scope.row.netEmission==null?'—':format(scope.row.netEmission,3) }}</template></el-table-column><el-table-column prop="totalCost" label="总成本（万元）"><template #default="scope">{{ scope.row.totalCost==null?'—':format(scope.row.totalCost,4) }}</template></el-table-column><el-table-column label="报告" width="180"><template #default="scope"><el-button link type="primary" @click="report(scope.row.id,'excel')">Excel</el-button><el-button link type="primary" @click="report(scope.row.id,'pdf')">PDF</el-button></template></el-table-column><el-table-column label="快照" width="90"><template #default="scope"><el-button link @click="viewVersion(scope.row.id)">查看</el-button></template></el-table-column></el-table></div></section>
    <section v-else class="workspace-section"><div v-if="pageStats.length" class="stat-grid"><div v-for="item in pageStats" :key="item.label" class="stat-card"><span>{{ item.label }}</span><strong>{{ item.value }}</strong><small>{{ item.unit }}</small></div></div><div class="panel"><div class="panel-heading"><div><h2>{{ active==='build'?'建材生产':active==='transport'?'运输':active==='construction'?'施工':'回收' }}记录</h2><p class="muted">{{ active==='recycling' ? '自动联动记录来自建材回收因子；自定义记录可手动维护' : '数据保存后立即参与服务端核算' }}</p></div><div v-if="active==='build'||active==='transport'||active==='construction'" class="toolbar-actions"><label class="upload-button">导入清单<input type="file" accept=".xlsx" hidden :disabled="!!importLoading" @change="importFile(active==='build'?'build-materials':active==='transport'?'transport-records':'construction-records',$event)"/></label><el-button @click="exportFile(active==='build'?'build-materials':active==='transport'?'transport-records':'construction-records')">导出清单</el-button></div></div><div v-if="active==='build'" class="entry-form"><el-select v-model="materialForm.factorConfigId" placeholder="选择建材因子" filterable><el-option v-for="item in buildFactors" :key="item.id" :value="item.id" :label="`${item.name} · ${item.category}`"/></el-select><el-input-number v-model="materialForm.quantity" :min="0.000001" placeholder="用量"/><el-input-number v-model="materialForm.marketPrice" :min="0" placeholder="市场价（元）"/><el-input-number v-model="materialForm.unitPrice" :min="0.000001" placeholder="成交价（元）"/><el-button type="primary" @click="addMaterial">新增建材</el-button></div><div v-else-if="active==='transport'" class="entry-form"><el-select v-model="transportForm.factorConfigId" placeholder="选择车辆"><el-option v-for="item in transportFactors" :key="item.id" :value="item.id" :label="`${item.vehicleName} · ${item.energyType}`"/></el-select><el-input v-model="transportForm.transportedMaterial" placeholder="运输货物"/><el-input-number v-model="transportForm.transportQuantity" :min="0.000001" placeholder="运输量"/><el-input-number v-model="transportForm.transportDistance" :min="0.000001" placeholder="运距"/><el-input-number v-model="transportForm.transportUnitPrice" :min="0" placeholder="运输单价"/><el-button type="primary" @click="addTransport">手动录入</el-button></div><div v-else-if="active==='construction'" class="entry-form"><el-input v-model="constructionForm.machineryName" placeholder="机械名称"/><el-select v-model="constructionForm.energyType"><el-option label="电力" value="电力"/><el-option label="柴油" value="柴油"/><el-option label="汽油" value="汽油"/></el-select><el-input-number v-model="constructionForm.shiftCount" :min="1" placeholder="台班数"/><el-input-number v-model="constructionForm.energyPerShift" :min="0.000001" placeholder="单位台班能耗"/><el-input-number v-model="constructionForm.shiftUnitPrice" :min="0" placeholder="台班单价"/><el-button type="primary" @click="addConstruction">新增台班</el-button></div><div v-else-if="active==='recycling'" class="entry-form"><el-input v-model="recyclingForm.materialName" placeholder="材料名称"/><el-select v-model="recyclingForm.materialType"><el-option v-for="t in recyclingTypes.slice(1)" :key="t" :label="t" :value="t"/></el-select><el-input-number v-model="recyclingForm.recyclingQuantity" :min="0.000001" placeholder="回收量"/><el-input-number v-model="recyclingForm.recyclingFactor" :min="0" placeholder="回收因子"/><el-input-number v-model="recyclingForm.recyclingCoefficient" :min="0" placeholder="回收系数"/><el-input-number v-model="recyclingForm.recyclingUnitPrice" :min="0" placeholder="回收单价"/><el-button type="primary" @click="addRecycling">新增回收材料</el-button></div><div class="filter-row"><el-input v-if="active==='build'" v-model="buildSearch" placeholder="搜索建材" clearable/><el-input v-else-if="active==='transport'" v-model="transportSearch" placeholder="搜索车辆或货物" clearable/><el-input v-else-if="active==='construction'" v-model="constructionSearch" placeholder="搜索机械" clearable/><el-input v-else v-model="recyclingSearch" placeholder="搜索材料" clearable/><div class="filter-pills"><button v-for="item in active==='build'?categories:active==='transport'?energyTypes:active==='construction'?constructionTypes:recyclingTypes" :key="item" :class="{active:(active==='build'?buildType:active==='transport'?transportEnergy:active==='construction'?constructionEnergy:recyclingType)===item}" @click="active==='build'?buildType=item:active==='transport'?transportEnergy=item:active==='construction'?constructionEnergy=item:recyclingType=item">{{ item }}</button></div></div><el-table v-if="active==='build'" :data="filteredBuild" stripe><el-table-column type="index" label="序号" width="70"/><el-table-column prop="materialName" label="材料名称"/><el-table-column prop="type" label="类型"/><el-table-column prop="unit" label="单位"/><el-table-column prop="quantity" label="用量"/><el-table-column prop="emissionFactor" label="因子"/><el-table-column prop="emissionAmount" label="碳排（t）"/><el-table-column prop="marketPrice" label="市场价"/><el-table-column prop="unitPrice" label="成交价"/><el-table-column label="操作" width="130"><template #default="s"><el-button link type="primary" @click="editing[`build-materials-${s.row.id}`]=!editing[`build-materials-${s.row.id}`]">{{ editing[`build-materials-${s.row.id}`]?'编辑中':'编辑' }}</el-button><el-button link type="danger" @click="removeRecord('build-materials',s.row.id)">删除</el-button><el-button v-if="editing[`build-materials-${s.row.id}`]" link type="success" @click="editRecord('build-materials',s.row)">保存</el-button></template></el-table-column></el-table><el-table v-else-if="active==='transport'" :data="filteredTransport" stripe><el-table-column type="index" label="序号" width="70"/><el-table-column prop="vehicleName" label="车辆"/><el-table-column prop="transportedMaterial" label="货物"/><el-table-column prop="transportQuantity" label="运输量"/><el-table-column prop="transportDistance" label="运距(km)"/><el-table-column prop="energyType" label="能源"/><el-table-column prop="emissionAmount" label="碳排（t）"/><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="editing[`transport-records-${s.row.id}`]=!editing[`transport-records-${s.row.id}`]">编辑</el-button><el-button link type="danger" @click="removeRecord('transport-records',s.row.id)">删除</el-button><el-button v-if="editing[`transport-records-${s.row.id}`]" link type="success" @click="editRecord('transport-records',s.row)">保存</el-button></template></el-table-column></el-table><el-table v-else-if="active==='construction'" :data="filteredConstruction" stripe><el-table-column type="index" label="序号" width="70"/><el-table-column prop="machineryName" label="机械"/><el-table-column prop="shiftCount" label="台班数"/><el-table-column prop="energyType" label="能源"/><el-table-column prop="energyPerShift" label="单位能耗"/><el-table-column prop="totalEnergy" label="能源总耗"/><el-table-column prop="emissionAmount" label="碳排（tCO₂e）"><template #default="s">{{ format(s.row.emissionAmount/1000,3) }}</template></el-table-column><el-table-column prop="totalPrice" label="总价（万元）"><template #default="s">{{ format(s.row.totalPrice,4) }}</template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="editing[`construction-records-${s.row.id}`]=!editing[`construction-records-${s.row.id}`]">编辑</el-button><el-button link type="danger" @click="removeRecord('construction-records',s.row.id)">删除</el-button><el-button v-if="editing[`construction-records-${s.row.id}`]" link type="success" @click="editRecord('construction-records',s.row)">保存</el-button></template></el-table-column></el-table><el-table v-else :data="filteredRecycling" stripe><el-table-column type="index" label="序号" width="70"/><el-table-column prop="materialName" label="材料"/><el-table-column prop="materialType" label="类别"/><el-table-column prop="recyclingQuantity" label="回收量"/><el-table-column prop="recyclingFactor" label="回收因子"/><el-table-column prop="recyclingCoefficient" label="回收系数"/><el-table-column prop="reductionAmount" label="减排（t）"/><el-table-column prop="residualValue" label="残值（万元）"/><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="editing[`recycling-records-${s.row.id}`]=!editing[`recycling-records-${s.row.id}`]">编辑</el-button><el-button v-if="s.row.isCustomMaterial" link type="danger" @click="removeRecord('recycling-records',s.row.id)">删除</el-button><el-button v-if="editing[`recycling-records-${s.row.id}`]" link type="success" @click="editRecord('recycling-records',s.row)">保存</el-button><span v-if="!s.row.isCustomMaterial" class="muted">自动联动</span></template></el-table-column></el-table></div></section>
  <el-dialog v-model="snapshotDialog" :title="`版本快照 v${snapshotData?.versionNumber || ''}`" width="760px"><div v-if="snapshotData"><dl class="detail-list"><dt>保存时间</dt><dd>{{ new Date(snapshotData.savedAt).toLocaleString() }}</dd><dt>项目名称</dt><dd>{{ snapshotData.project?.projectName }}</dd><dt>建筑面积</dt><dd>{{ format(snapshotData.project?.buildingArea, 0) }} ㎡</dd><dt>建材记录</dt><dd>{{ snapshotData.buildMaterials?.length || 0 }} 条</dd><dt>运输记录</dt><dd>{{ snapshotData.transportRecords?.length || 0 }} 条</dd><dt>施工记录</dt><dd>{{ snapshotData.constructionRecords?.length || 0 }} 条</dd><dt>回收记录</dt><dd>{{ snapshotData.recyclingRecords?.length || 0 }} 条</dd><dt>净碳排放</dt><dd>{{ format(snapshotData.summary?.emission?.netEmission, 6) }} tCO₂e</dd><dt>总成本</dt><dd>{{ format(snapshotData.summary?.cost?.totalCost, 4) }} 万元</dd></dl><h3>阶段排放</h3><div v-for="stage in snapshotData.summary?.emission?.stages || []" :key="stage.name" class="analysis-line"><span>{{ stage.name }}</span><strong>{{ format(stage.emission, 6) }} tCO₂e</strong></div></div><template #footer><el-button @click="snapshotDialog=false">关闭</el-button></template></el-dialog>
  </div>
</template>
